insert into knowledge.public_sources(source_key,version,title,source_ref,excerpt,metadata,status,reviewed_at) values
('mei-limite',1,'MEI: limite de receita anual e início de atividade','https://www.gov.br/memp/pt-br/teto-do-mei','A página do Ministério do Empreendedorismo consultada em 06/11/2026 informa limite anual de receita do MEI de R$ 81 mil e proporcionalidade aos meses de atividade no ano de abertura. O texto da página ainda apresenta aumentos de 2027 e 2028 como proposta. Esta fonte pode estar desatualizada quanto à tramitação: confira também a publicação posterior da Câmara. Não aplicar este trecho automaticamente a outro ano ou a categorias especiais.','{"authority": "MEMP", "jurisdiction": "BR", "regime": "unknown", "classification": "informational_curated_summary", "publishedOn": null, "validFrom": null, "validTo": null, "validitySource": "", "reviewedOn": "2026-11-06"}'::jsonb,'published','2026-11-06T12:00:00Z'),
('mei-limite-atualizacao',1,'MEI: notícia de atualização legislativa do limite anual','https://www.camara.leg.br/noticias/1312953-noticia','Agência Câmara, notícia de 21/10/2026: relata publicação de lei complementar com aumento do teto anual do MEI de R$ 81 mil para R$ 110 mil em 2027 e R$ 140 mil em 2028. É relato informativo, não verificação da íntegra da lei nem cálculo do limite de uma empresa. Há diferença de atualização em relação à página ministerial anterior; confirme o ano-calendário, a norma aplicável e situações especiais antes de concluir o enquadramento.','{"authority": "Agência Câmara", "jurisdiction": "BR", "regime": "unknown", "classification": "informational_curated_summary", "publishedOn": null, "validFrom": null, "validTo": null, "validitySource": "", "reviewedOn": "2026-11-06"}'::jsonb,'published','2026-11-06T12:00:00Z'),
('mei-dasn',1,'MEI: declaração anual DASN-SIMEI','https://www.gov.br/pt-br/servicos/declarar-receita-bruta-anual-para-o-mei','O serviço oficial DASN-SIMEI recebe a informação de receita bruta anual do MEI e de contratação de empregado, quando houver. A orientação geral informa entrega até o último dia de maio do ano seguinte ao ano-calendário declarado. Extinção tem prazos próprios. Consulte o período e eventuais prorrogações; este trecho não transmite declaração nem comprova cumprimento da obrigação.','{"authority": "GOV.BR", "jurisdiction": "BR", "regime": "unknown", "classification": "informational_curated_summary", "publishedOn": null, "validFrom": null, "validTo": null, "validitySource": "", "reviewedOn": "2026-11-06"}'::jsonb,'published','2026-11-06T12:00:00Z'),
('nfse-emissores',1,'Nota fiscal de serviços NFS-e: MEI e demais empresas','https://www.gov.br/nfse/pt-br/pagina-inicial/','O Portal Nacional informa uso da NFS-e de padrão nacional para MEI prestador de serviços desde setembro de 2023. Para prestadores que não são MEI, o portal condiciona o uso dos emissores públicos à existência de convênio ativo do município. Cadastro, autenticação e operação devem ser conferidos no cenário concreto. Uma consulta de fontes ou preparação de rascunho não emite nota fiscal.','{"authority": "Portal Nacional NFS-e", "jurisdiction": "BR", "regime": "unknown", "classification": "informational_curated_summary", "publishedOn": null, "validFrom": null, "validTo": null, "validitySource": "", "reviewedOn": "2026-11-06"}'::jsonb,'published','2026-11-06T12:00:00Z'),
('simples-conceito',1,'Simples Nacional: opção e requisitos para ME e EPP','https://www8.receita.fazenda.gov.br/SimplesNacional/Documentos/Pagina.aspx?id=3','A Receita Federal apresenta o Simples Nacional como regime de arrecadação de tributos destinado a microempresas e empresas de pequeno porte. Para ingressar, a empresa precisa atender aos requisitos legais e formalizar a opção. Não ser MEI não confirma opção pelo Simples Nacional. Esta síntese não define anexo, alíquota, tributação de uma atividade nem o regime de uma empresa.','{"authority": "Receita Federal", "jurisdiction": "BR", "regime": "unknown", "classification": "informational_curated_summary", "publishedOn": null, "validFrom": null, "validTo": null, "validitySource": "", "reviewedOn": "2026-11-06"}'::jsonb,'published','2026-11-06T12:00:00Z')
